    "…ありがとうございます。…休みます。": "...Thank you. ...I'll rest.",
    "…ありがとうございます。…優しい。": "...Thank you. ...How kind.",
    "…ありがとうございます。…助かります。": "...Thank you. ...That's a real help.",
    "…ありがとうございます。…嬉しい、です。": "...Thank you. ...I'm glad.",
    "…ありがとうございます。…嬉しいです。": "...Thank you. ...That makes me happy.",
