    "…ありがとうございます。…少し、休みます。": "...Thank you. ...I'll rest a little.",
    "…ありがとうございます。…止まれませんから。": "...Thank you. ...There is no stopping.",
    "…ありがとうございます。…気を遣っていただいて。": "...Thank you. ...For going easy on me.",
    "…ありがとうございます。…申し訳ない、です。": "...Thank you. ...And I'm sorry.",
    "…ありがとうございます。…私、止まれないから。": "...Thank you. ...There's no stopping me now.",
