    "…ありがとうございます。…私の代わりに、みんなを見てくださって。": "...Thank you. ...For watching over them in my place.",
    "…ありがとうございます。…私の代わりに、メンバーを見てくださって。": "...Thank you. ...For looking after the members while I couldn't.",
    "…ありがとうございます。…続けます。": "...Thank you. ...We'll keep going.",
    "…ありがとうございます。…見ていただけていたんですね。": "...Thank you. ...So you had been watching.",
    "…ありがとうございます。…見ていてくださったんですね、安心しました。": "...Thank you. ...You were watching after all. That's a relief.",
