    "…ありがとうございます。…見てくれてたんですね、嬉しい。": "...Thank you. ...You were watching. That's lovely.",
    "…ありがとうございます。…見ててくれたんすね。": "...Thanks. ...So you were watching after all.",
    "…ありがとうございます。…見てもらえてたんですね。": "...Thank you. ...So it was being seen.",
    "…ありがとうございます。…見てもらえてるんだ、って、安心しました。": "...Thank you. ...Knowing we're actually seen — that settles me.",
    "…ありがとうございます。…見守ってください。": "...Thank you. ...Just keep watching over us.",
    "…ありがとうございます。いただいた寛容に甘え過ぎないようにします。": "...Thank you. I won't lean too far on the room you've given us.",
    "…ありがとうございます。お気持ち、しっかり受け取ります。": "...Thank you. I'll take what you meant by it, and hold on to it.",
