    "負けず嫌いは損な性分だけどさ、こういう時だけは役に立つね": "Hating to lose is a costly way to be, but it earns its keep on nights like this.",
    "負けず嫌い結構。事実、負けてないからね": "Call me a sore loser. Fine. I haven't lost, have I.",
    "負けた…っ…でも、この気持ち…絶対に忘れないわ…": "I lost... But this feeling... I'll never forget it...",
    "負けたか。…ま、次があるさ": "Lost that one. ...Well, there's always the next.",
    "負けたくない…この気持ちが一番の武器！": "I hate losing... and that's the best weapon I've got!",
    "負けたままでいられるか…{partner}、次は倍返しだ！": "I'm not leaving it like this... {partner}, next time we pay it back double!",
    "負けたわ。でも…諦めないの。必ず返すから": "I lost. But... I'm not giving up. I'll collect on it.",
    "負けてしまいました。でも次は必ずやり返します！": "I lost this one. But next time I'll take it back, definitely!",
    "負けてしまいましたわ。…でも次はやり返しますので！": "I lost, it seems. ...But the next one is mine!",
    "負けて無様な姿をさらして…　いい気味ね♪": "Beaten, sprawled out for everyone to see... it suits you ♪",
    "負けました。……でも諦めません。……必ず借りを返しますわ": "I lost. ...But I am not giving up. ...I will repay this, without fail.",
    "負けました。でも諦めません。必ず借りを返します": "I lost. But I'm not giving up. I'll pay this back.",
    "負け続きでも腐らなかった。…やっと報われた気がする！": "All those losses, and I never let myself quit. ...I think it finally paid off!",
    "身体能力じゃ勝てない。だから頭を使うの。": "I can't win on athleticism. So I use my head.",
    "迎えてくださった団体に、申し訳が立ちませんわ…倒れませんの。": "I could not face the promotion that took me in... I will not fall.",
