    "道を踏み外した？ …これが本当の私よ。": "Went off the rails, did I? ...This is who I actually am.",
    "選んでくれてありがとー！ 期待にはちゃんと応えるよ〜": "Thanks for picking me! I'll live up to it, promise~",
